-- Lane A figures for ap_statistics: generated by build_load_sql.py, do not hand-edit.
-- 2 figures across 1 families, from scripts/lane-a-pilot/specs.json.
-- Entries are resolved by natural key, so this file is portable between environments.

begin;

-- 1. The renderer families this batch INTRODUCES (DECISION-0115: a row, not a CHECK).
-- Reused without introducing: none
insert into app.figure_families (family_key, title, summary, renderer_note)
values ('categorical_bars', 'Categorical and binned bars', 'Bar chart, histogram, side-by-side, segmented and mosaic, as five modes of one rectangle geometry. Separated bars for a categorical variable, contiguous bars for a quantitative one, and mosaic bar widths proportional to the category totals.', 'scripts/lane-a-pilot/render.py; the app''s figure renderer')
on conflict (family_key) do nothing;

-- 2. The figures.
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-association-yes', 'ap_statistics', 'categorical_bars', 'Distributions that differ: associated in these data', 'Associated in these data', 'The pass rate differs between the two levels (figure 1 of 2)', 'Exam results for students with and without a part-time job: the two distributions differ.', 'A segmented bar chart comparing exam results for two groups of students. Among the 50 students with a part-time job, 60% pass and 40% do not. Among the 40 students without one, 80% pass and 20% do not. The two distributions of results differ, so in these data the variables are associated. Illustrative data.', 'part-time job', 'share of the group', 'Compare the distribution of the response within each level of the other variable; here the two differ.', true, null, '["Distribution of one variable within each level of the other", "Whether the distributions differ or match across levels"]'::jsonb, '{"mode": "segmented", "categories": ["Has a part-time job", "No part-time job"], "levels": ["Passes the exam", "Does not pass"], "table": [[30, 32], [20, 8]]}'::jsonb, '{:.0%}', null, 'published', 'cramapple-authored; batch=stats-next2-figures-2026-10-15', now())
on conflict (figure_id) do nothing;
insert into app.figures (figure_id, subject_key, family, title, short_title, subtitle, caption, alt, x_label, y_label, note, synthetic, values_note, labels, params, y_tick_fmt, x_tick_fmt, status, source_note, published_at)
values ('stats-association-no', 'ap_statistics', 'categorical_bars', 'Distributions that match: no association in these data', 'No association in these data', 'The pass rate is the same at both levels (figure 2 of 2)', 'Exam results for students with and without a part-time job: the two distributions match.', 'A segmented bar chart comparing exam results for two groups of students. Among the 50 students with a part-time job, 70% pass and 30% do not. Among the 40 students without one, 70% pass and 30% do not. The two distributions of results are the same, so in these data the variables are not associated. Illustrative data.', 'part-time job', 'share of the group', 'Compare the distribution of the response within each level of the other variable; here the two match.', true, null, '["Distribution of one variable within each level of the other", "Whether the distributions differ or match across levels"]'::jsonb, '{"mode": "segmented", "categories": ["Has a part-time job", "No part-time job"], "levels": ["Passes the exam", "Does not pass"], "table": [[35, 28], [15, 12]]}'::jsonb, '{:.0%}', null, 'published', 'cramapple-authored; batch=stats-next2-figures-2026-10-15', now())
on conflict (figure_id) do nothing;

-- 3. Where each figure is shown, resolved by natural key (protocol §6).
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-association-yes', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Judging association from two categorical variables' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;
insert into app.figure_uses (figure_id, reference_entry_id, role)
select 'stats-association-no', e.reference_entry_id, 'primary'
  from app.unit_reference_entries e
 where e.subject_key = 'ap_statistics' and e.kind = 'convention'
   and e.title = 'Judging association from two categorical variables' and e.status = 'published'
on conflict (figure_id, reference_entry_id) where reference_entry_id is not null do nothing;

-- 4. Guards: no dead figure, and every entry this batch covers got its figures.
do $$
declare v_dead text; v_n int;
begin
  select string_agg(f.figure_id, ', ') into v_dead
    from app.figures f left join app.figure_uses u on u.figure_id = f.figure_id
   where f.figure_id in ('stats-association-yes', 'stats-association-no') and u.figure_id is null;
  if v_dead is not null then
    raise exception 'figures with no use, refusing to ship dead rows: %', v_dead;
  end if;
  select count(*) into v_n from app.figures where figure_id in ('stats-association-yes', 'stats-association-no');
  if v_n <> 2 then
    raise exception 'expected 2 figures, found %', v_n;
  end if;
end $$;

commit;
